http.createServer(async(req,res)=>{
  try{
    headers(res);
    const url=new URL(req.url,`http://${req.headers.host||'localhost'}`);
    const pathname=decodeURIComponent(url.pathname).replace(/\/+$/,'')||'/';
    if(pathname==='/health'){const storage=storageHealth();return json(res,storage.ok?200:503,{ok:storage.ok,storage:storage.ok?'writable':'error'});}
    if(pathname==='/robots.txt')return text(res,200,'User-agent: *\nDisallow: /\n','text/plain; charset=utf-8');
    if(pathname.startsWith('/assets/'))return asset(pathname,res);
    if(pathname.startsWith('/media/'))return serveMedia(pathname,res);
    if(pathname.startsWith('/webhooks/starsender/'))return starSenderWebhook(req,res,pathname);
    if(pathname.startsWith('/go/'))return campaignRedirect(req,res,pathname,url);
    if(pathname==='/forms/consultation')return publicLeadForm(req,res,url);
    if(pathname==='/login'){
      if(req.method==='GET')return html(res,200,login());
      if(req.method==='POST')return loginPost(req,res);
      return text(res,405,'Method not allowed');
    }
    const auth=getAuth(req);
    if(!auth)return redirect(res,'/login');
    const {user,session}=auth;
    if(req.method==='POST'){
      req.body=await body(req,pathname==='/restore-backup'?16_000_000:['/messages','/broadcasts'].includes(pathname)?8_000_000:1_500_000);
      if(!safe(req.body.csrf,session.csrf))return html(res,403,layout(user,session,'Akses ditolak','',messageView('Akses ditolak','Sesi formulir tidak valid. Muat ulang halaman.')));
    }
    if(pathname==='/logout'&&req.method==='POST'){res.setHeader('Set-Cookie',clearCookie());return redirect(res,'/login')}
    if(pathname==='/')return guard(res,user,session,'dashboard',()=>html(res,200,layout(user,session,'Dashboard','dashboard',dashboard())));
    if(pathname==='/calendar')return guard(res,user,session,'calendar',()=>html(res,200,layout(user,session,'Kalender Konten','calendar',calendar(url.searchParams.get('month')))));
    if(pathname==='/reports')return guard(res,user,session,'reports',()=>html(res,200,layout(user,session,'Laporan','reports',reports())));
    if(pathname==='/crm')return guard(res,user,session,'crm',()=>crmRoute(req,res,user,session));
    if(pathname==='/copylab')return guard(res,user,session,'copylab',()=>copyLabRoute(req,res,user,session));
    if(pathname==='/integrations')return await guard(res,user,session,'integrations',()=>integrationsRoute(req,res,user,session));
    if(pathname==='/messages')return await guard(res,user,session,'messages',()=>messagesRoute(req,res,user,session));
    if(pathname==='/messages/sync-groups'&&req.method==='POST')return await guard(res,user,session,'messages',()=>syncGroupsRoute(req,res,user,session));
    if(pathname==='/broadcasts')return await guard(res,user,session,'broadcasts',()=>broadcastsRoute(req,res,user,session));
    if(pathname==='/whatsapp-live')return guard(res,user,session,'whatsapp-live',()=>starSenderWebWhatsAppRoute(res,user,session));
    const balance=pathname.match(/^\/promoters\/(\d+)\/voucher$/);
    if(balance)return await guard(res,user,session,'integrations',()=>voucherRoute(req,res,user,session,+balance[1]));
    if(pathname==='/profile')return profile(req,res,user,session);
    if(pathname==='/backup.json')return guard(res,user,session,'backup',()=>download(res,DB_FILE,`stifin-mulia-backup-${today()}.json`,'application/json'));
    if(pathname==='/backup-now'&&req.method==='POST')return guard(res,user,session,'backup',()=>backupNow(req,res,user));
    if(pathname==='/restore-backup'&&req.method==='POST')return guard(res,user,session,'backup',()=>restoreUploadedBackup(req,res,user));
    const exp=pathname.match(/^\/export\/(content|leads|promoters|referrals|campaigns)\.csv$/);
    if(exp)return guard(res,user,session,'reports',()=>csv(res,exp[1]));
    const route=match(pathname);
    if(route)return resource(req,res,url,user,session,route);
    return html(res,404,layout(user,session,'Tidak ditemukan','',messageView('Halaman tidak ditemukan','Alamat yang dibuka tidak tersedia.')));
  }catch(e){console.error(e);if(!res.headersSent)html(res,e.statusCode||500,login(e.statusCode===413?'Data terlalu besar untuk diproses.':'Terjadi kendala pada aplikasi. Silakan coba kembali.'));else res.end()}
}).listen(PORT,'0.0.0.0',()=>console.log(`${APP_NAME} aktif pada port ${PORT}`));

function initDb(){
  fs.mkdirSync(DATA_DIR,{recursive:true});fs.mkdirSync(BACKUP_DIR,{recursive:true});fs.mkdirSync(MEDIA_DIR,{recursive:true});
  const health=storageHealth();if(!health.ok)throw new Error(`Penyimpanan tidak dapat ditulis: ${health.error}`);
  if(fs.existsSync(DB_FILE)){
    try{state=JSON.parse(fs.readFileSync(DB_FILE,'utf8'));normalize();createBackup('startup');return}
    catch(error){const recovered=restoreLatestBackup();if(recovered){state=recovered;normalize();save({skipBackup:true});console.warn('[STORAGE] Database dipulihkan dari cadangan terakhir.');return}throw new Error(`Database rusak dan tidak ada cadangan yang valid: ${error.message}`)}
  }
  const password=process.env.APP_ADMIN_PASSWORD||`SM-${crypto.randomBytes(9).toString('base64url')}`;if(!process.env.APP_ADMIN_PASSWORD)console.warn(`[SETUP] Password awal satu kali: ${password}`);
  state={meta:{version:6,installationId:crypto.randomUUID(),createdAt:new Date().toISOString(),appKey:process.env.APP_KEY||crypto.randomBytes(48).toString('base64url'),next:{users:2,content:121,leads:1,promoters:1,referrals:1,templates:17,activity:1,messages:1,integrationRuns:1,webhookEvents:1,campaigns:1,campaignEvents:1,copyDrafts:1,conversations:1,groups:1,conversationNotes:1,recipientPresets:1,broadcastRuns:1}},users:[{id:1,name:'Pemilik STIFIn Mulia',email:String(process.env.APP_ADMIN_EMAIL||'admin@stifinmulia.com').toLowerCase(),role:'owner',passwordHash:hash(password),active:true,createdAt:new Date().toISOString()}],content:seedContent(),leads:[],promoters:[],referrals:[],templates:seedTemplates(),activity:[],messages:[],integrationRuns:[],webhookEvents:[],campaigns:[],campaignEvents:[],copyDrafts:[],conversations:[],groups:[],conversationNotes:[],recipientPresets:[],broadcastRuns:[]};save({skipBackup:true});createBackup('initial');
}
function normalize(){const collections=['users','content','leads','promoters','referrals','templates','activity','messages','integrationRuns','webhookEvents','campaigns','campaignEvents','copyDrafts','conversations','groups','conversationNotes','recipientPresets','broadcastRuns'];for(const k of collections)state[k]??=[];state.meta??={};state.meta.version=6;state.meta.installationId??=crypto.randomUUID();state.meta.createdAt??=new Date().toISOString();state.meta.next??={};state.meta.appKey??=process.env.APP_KEY||crypto.randomBytes(48).toString('base64url');for(const k of collections)state.meta.next[k]??=Math.max(0,...state[k].map(x=>Number(x.id)||0))+1;migrateConversations()}
function save(options={}){if(!options.skipBackup)createBackup('auto');const tmp=`${DB_FILE}.${process.pid}.tmp`;fs.writeFileSync(tmp,JSON.stringify(state,null,2),{mode:0o600});fs.renameSync(tmp,DB_FILE)}
function storageHealth(){try{fs.mkdirSync(DATA_DIR,{recursive:true});const probe=path.join(DATA_DIR,`.write-test-${process.pid}`);fs.writeFileSync(probe,'ok');fs.unlinkSync(probe);return {ok:true}}catch(error){return {ok:false,error:String(error.message||error)}}}
function backupFiles(){try{return fs.readdirSync(BACKUP_DIR).filter(x=>/^database-.*\.json$/.test(x)).sort().reverse()}catch{return []}}
function createBackup(reason='manual',force=false){
  if(!fs.existsSync(DB_FILE))return null;
  const now=Date.now();if(!force&&now-lastBackupAt<BACKUP_INTERVAL_MS)return null;
  fs.mkdirSync(BACKUP_DIR,{recursive:true});
  const stamp=new Date(now).toISOString().replace(/[:.]/g,'-');const target=path.join(BACKUP_DIR,`database-${stamp}-${reason}.json`);
  JSON.parse(fs.readFileSync(DB_FILE,'utf8'));fs.copyFileSync(DB_FILE,target);fs.chmodSync(target,0o600);lastBackupAt=now;
  for(const old of backupFiles().slice(BACKUP_RETENTION))fs.unlinkSync(path.join(BACKUP_DIR,old));
  return target;
}
function restoreLatestBackup(){for(const file of backupFiles()){try{return JSON.parse(fs.readFileSync(path.join(BACKUP_DIR,file),'utf8'))}catch{}}return null}
function storageSummary(){const files=backupFiles();let size=0;try{size=fs.statSync(DB_FILE).size}catch{}return {ok:storageHealth().ok,path:DB_FILE,installationId:state?.meta?.installationId||'-',databaseSize:size,backups:files.length,lastBackup:files[0]||''}}
function backupNow(req,res,user){if(!['owner','admin'].includes(user.role))return text(res,403,'Akses ditolak');const file=createBackup('manual',true);activity(user,'membuat','cadangan database',file?path.basename(file):'tidak tersedia');return redirect(res,'/integrations?backup=success')}
function validateBackup(candidate){
  if(!candidate||typeof candidate!=='object'||Array.isArray(candidate))throw new Error('Berkas bukan cadangan JSON yang valid.');
  if(!candidate.meta||typeof candidate.meta!=='object')throw new Error('Metadata cadangan tidak ditemukan.');
  const required=['users','content','leads','promoters','referrals','templates'];
  for(const key of required)if(!Array.isArray(candidate[key]))throw new Error(`Bagian ${key} tidak valid atau tidak tersedia.`);
  if(!candidate.users.length||!candidate.users.some(x=>x&&x.role==='owner'&&x.active!==false&&x.passwordHash))throw new Error('Cadangan tidak memiliki akun pemilik aktif yang valid.');
  return candidate;
}
function restoreUploadedBackup(req,res,user){
  if(!['owner','admin'].includes(user.role))return text(res,403,'Akses ditolak');
  try{
    const raw=String(req.body?.backupData||'').trim();
    if(!raw)throw new Error('Pilih berkas cadangan JSON terlebih dahulu.');
    if(Buffer.byteLength(raw)>5_000_000)throw new Error('Ukuran cadangan melebihi batas 5 MB.');
    const restored=validateBackup(JSON.parse(raw));
    const currentSecurity={appKey:state.meta.appKey,installationId:state.meta.installationId,createdAt:state.meta.createdAt};
    createBackup('before-restore',true);
    state=restored;normalize();
    state.meta.appKey=currentSecurity.appKey;
    state.meta.installationId=currentSecurity.installationId;
    state.meta.createdAt=currentSecurity.createdAt;
    state.meta.restoredAt=new Date().toISOString();
    state.meta.restoredBy=user.name;
    save({skipBackup:true});
    activity(user,'memulihkan','cadangan database',`${state.leads.length} lead, ${state.promoters.length} promotor`);
    return redirect(res,'/integrations?restore=success');
  }catch(error){
    return redirect(res,`/integrations?restore=error&detail=${encodeURIComponent(String(error.message||error).slice(0,180))}`);
  }
}
function insert(k,r){const now=new Date().toISOString();const x={id:state.meta.next[k]++,...r,createdAt:r.createdAt||now,updatedAt:now};state[k].push(x);save();return x}
function update(k,id,r){const x=state[k].find(x=>Number(x.id)===Number(id));if(!x)return null;Object.assign(x,r,{updatedAt:new Date().toISOString()});save();return x}
function remove(k,id){const n=state[k].findIndex(x=>Number(x.id)===Number(id));if(n<0)return false;state[k].splice(n,1);save();return true}
function refreshCampaignMetrics(){for(const campaign of state.campaigns){const leads=state.leads.filter(x=>x.campaignCode===campaign.code);campaign.leads=leads.length;campaign.bookings=leads.filter(x=>['Booking','Tes selesai','Tindak lanjut'].includes(x.status)).length}}
function activity(user,action,subject,detail=''){state.activity.unshift({id:state.meta.next.activity++,userName:user?.name||'Sistem',action,subject,detail,createdAt:new Date().toISOString()});state.activity=state.activity.slice(0,1000);refreshCampaignMetrics();save()}
function hash(p,s=crypto.randomBytes(16).toString('hex')){return `${s}:${crypto.scryptSync(String(p),s,64).toString('hex')}`}
function verify(p,v){if(!v?.includes(':'))return false;const[s,e]=v.split(':');const a=crypto.scryptSync(String(p),s,64),b=Buffer.from(e,'hex');return a.length===b.length&&crypto.timingSafeEqual(a,b)}
function token(user){const p={uid:user.id,csrf:crypto.randomBytes(24).toString('base64url'),exp:Math.floor(Date.now()/1000)+43200};const v=Buffer.from(JSON.stringify(p)).toString('base64url');return `${v}.${crypto.createHmac('sha256',state.meta.appKey).update(v).digest('base64url')}`}
function session(t){try{const[v,s]=String(t||'').split('.');const e=crypto.createHmac('sha256',state.meta.appKey).update(v).digest('base64url');if(!safe(s,e))return null;const p=JSON.parse(Buffer.from(v,'base64url'));return p.exp>Date.now()/1000?p:null}catch{return null}}
function cookies(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').map(x=>x.trim().split('=').map(decodeURIComponent)))}
function getAuth(req){const s=session(cookies(req).stifin_session);if(!s)return null;const user=state.users.find(x=>Number(x.id)===Number(s.uid)&&x.active);return user?{user,session:s}:null}
function cookie(t){return `stifin_session=${encodeURIComponent(t)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=43200${SECURE?'; Secure':''}`}
function clearCookie(){return `stifin_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${SECURE?'; Secure':''}`}
function allowed(role,key){return permissions[role]?.includes('*')||permissions[role]?.includes(key)}

async function loginPost(req,res){const ip=String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'').split(',')[0];let a=loginAttempts.get(ip)||{count:0,at:Date.now()};if(Date.now()-a.at>900000)a={count:0,at:Date.now()};if(a.count>=10)return html(res,429,login('Terlalu banyak percobaan. Tunggu 15 menit.'));const b=await body(req),email=String(b.email||'').trim().toLowerCase(),user=state.users.find(x=>x.email===email&&x.active);if(!user||!verify(b.password||'',user.passwordHash)){a.count++;loginAttempts.set(ip,a);return html(res,401,login('Email atau password tidak sesuai.',email))}loginAttempts.delete(ip);res.setHeader('Set-Cookie',cookie(token(user)));activity(user,'masuk ke','dashboard');return redirect(res,'/')}
async function profile(req,res,user,s){if(req.method==='GET')return html(res,200,layout(user,s,'Profil','',profileForm(user,s.csrf)));if(req.method!=='POST')return text(res,405,'Method not allowed');const b=req.body,name=String(b.name||'').trim();let error='';if(!name)error='Nama wajib diisi.';if(b.newPassword){if(!verify(b.currentPassword||'',user.passwordHash))error='Password saat ini tidak sesuai.';else if(String(b.newPassword).length<10)error='Password baru minimal 10 karakter.';else if(b.newPassword!==b.confirmPassword)error='Pengulangan password tidak sama.'}if(error)return html(res,422,layout(user,s,'Profil','',profileForm({...user,name},s.csrf,error)));const changes={name};if(b.newPassword)changes.passwordHash=hash(b.newPassword);update('users',user.id,changes);activity({...user,name},'memperbarui','profil');return html(res,200,layout({...user,name},s,'Profil','',profileForm({...user,name},s.csrf,'','Profil berhasil diperbarui.')))}

function match(p){const a=p.split('/').filter(Boolean),key=a[0];if(!defs[key])return null;if(a.length===1)return{key,mode:'list'};if(a.length===2&&a[1]==='new')return{key,mode:'new'};if(a.length===3&&/^\d+$/.test(a[1])&&a[2]==='edit')return{key,mode:'edit',id:+a[1]};if(a.length===2&&/^\d+$/.test(a[1]))return{key,mode:'save',id:+a[1]};if(a.length===3&&/^\d+$/.test(a[1])&&a[2]==='delete')return{key,mode:'delete',id:+a[1]};return null}
function resource(req,res,url,user,s,r){const d=defs[r.key];if(!allowed(user.role,r.key))return html(res,403,layout(user,s,'Akses ditolak','',messageView('Akses tidak tersedia','Peran akun Anda tidak memiliki izin.')));const readonly=user.role==='viewer';if(r.mode==='list'&&req.method==='GET'){const q=String(url.searchParams.get('q')||'').toLowerCase(),st=String(url.searchParams.get('status')||'');let rows=state[r.key].filter(x=>!q||d.search.some(k=>String(x[k]||'').toLowerCase().includes(q)));if(st)rows=rows.filter(x=>x.status===st);rows=[...rows].sort((a,b)=>b.id-a.id);const total=rows.length,pages=Math.max(1,Math.ceil(total/25)),page=Math.min(pages,Math.max(1,+url.searchParams.get('page')||1));return html(res,200,layout(user,s,d.label,r.key,listView(r.key,d,rows.slice((page-1)*25,page*25),total,q,st,page,pages,user,s.csrf),url.searchParams.get('message')||''))}if(r.mode==='new'&&req.method==='GET'&&!readonly)return html(res,200,layout(user,s,`Tambah ${d.single}`,r.key,formView(r.key,d,{},s.csrf)));if(r.mode==='edit'&&req.method==='GET'){const x=state[r.key].find(x=>x.id===r.id);return x?html(res,200,layout(user,s,d.single,r.key,formView(r.key,d,x,s.csrf,[],readonly))):html(res,404,layout(user,s,'Tidak ditemukan','',messageView('Data tidak ditemukan','Data mungkin sudah dihapus.')))}if(readonly)return html(res,403,layout(user,s,'Akses ditolak','',messageView('Akses tidak tersedia','Akun viewer hanya dapat membaca data.')));if(r.mode==='list'&&req.method==='POST')return saveResource(res,user,s,r.key,d,null,req.body);if(r.mode==='save'&&req.method==='POST')return saveResource(res,user,s,r.key,d,r.id,req.body);if(r.mode==='delete'&&req.method==='POST'){const x=state[r.key].find(x=>x.id===r.id);if(!x)return redirect(res,`/${r.key}?message=Data+tidak+ditemukan`);if(r.key==='users'&&x.id===user.id)return redirect(res,'/users?message=Akun+yang+sedang+dipakai+tidak+dapat+dihapus');if(r.key==='users'&&x.role==='owner'&&state.users.filter(y=>y.role==='owner'&&y.active).length<=1)return redirect(res,'/users?message=Pemilik+aktif+terakhir+tidak+dapat+dihapus');remove(r.key,r.id);activity(user,'menghapus',d.single,x.title||x.name||x.participantName||x.code);return redirect(res,`/${r.key}?message=Data+berhasil+dihapus`)}return text(res,405,'Method not allowed')}
function saveResource(res,user,s,key,d,id,b){const existing=id?state[key].find(x=>x.id===id):null;if(id&&!existing)return html(res,404,layout(user,s,'Tidak ditemukan','',messageView('Data tidak ditemukan','Data mungkin sudah dihapus.')));const record={};for(const f of d.fields){const[n,,type]=f;if(n==='newPassword')continue;if(type==='checkbox')record[n]=b[n]==='on';else if(type==='number')record[n]=b[n]?Number(b[n]):0;else record[n]=String(b[n]||'').trim()}const errors=[];for(const f of d.fields)if(f[3]&&f[0]!=='newPassword'&&!record[f[0]])errors.push(`${f[1]} wajib diisi.`);if(key==='campaigns'){record.code=record.code.toUpperCase().replace(/[^A-Z0-9-]/g,'-').replace(/-+/g,'-');if(state.campaigns.some(x=>x.code===record.code&&x.id!==id))errors.push('Kode kampanye sudah digunakan.')}if(key==='users'){record.email=record.email.toLowerCase();if(state.users.some(x=>x.email===record.email&&x.id!==id))errors.push('Email sudah digunakan.');if(!id&&String(b.newPassword||'').length<10)errors.push('Password minimal 10 karakter.');if(b.newPassword&&String(b.newPassword).length<10)errors.push('Password minimal 10 karakter.');if(existing?.role==='owner'&&record.role!=='owner'&&state.users.filter(x=>x.role==='owner'&&x.active).length<=1)errors.push('Peran pemilik aktif terakhir tidak dapat diubah.')}if(errors.length)return html(res,422,layout(user,s,d.single,key,formView(key,d,{...existing,...record,id},s.csrf,errors)));if(key==='users'&&b.newPassword)record.passwordHash=hash(b.newPassword);const x=id?update(key,id,record):insert(key,record);if(key==='leads'&&record.status==='Booking'&&existing?.status!=='Booking'&&record.campaignCode){const campaign=state.campaigns.find(c=>c.code===record.campaignCode);if(campaign)update('campaigns',campaign.id,{bookings:Number(campaign.bookings||0)+1})}activity(user,id?'memperbarui':'menambahkan',d.single,x.title||x.name||x.participantName||x.code);return redirect(res,`/${key}?message=Data+berhasil+disimpan`)}

function login(error='',email=''){return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Masuk | ${esc(APP_NAME)}</title><link rel="stylesheet" href="/assets/app.css"></head><body class="login-body"><main class="login-card"><div class="login-logo">SM</div><p class="eyebrow">STIFIn MULIA</p><h1>Marketing Hub</h1><p class="muted">Pusat bank konten, calon peserta, promotor, dan jaringan layanan.</p>${error?`<div class="alert bad">${esc(error)}</div>`:''}<form method="post" class="stack"><label>Email<input type="email" name="email" value="${esc(email)}" required autofocus></label><label>Password<input type="password" name="password" required></label><button class="btn primary">Masuk ke Dashboard</button></form><p class="muted">Aplikasi internal. Tidak tersedia pendaftaran publik.</p></main></body></html>`}
function layout(user,s,title,active,content,flash=''){const nav=[['dashboard','/','Dashboard'],['crm','/crm','Growth CRM'],['messages','/messages','Communication Center'],['broadcasts','/broadcasts','Kirim Massal'],['whatsapp-live','/whatsapp-live','WhatsApp Live',true],['campaigns','/campaigns','Kampanye'],['calendar','/calendar','Kalender'],['content','/content','Bank Konten'],['copylab','/copylab','Copywriting Lab'],['leads','/leads','Lead dan Peserta'],['promoters','/promoters','Promotor'],['referrals','/referrals','Rujukan Wilayah'],['templates','/templates','Skrip WhatsApp'],['integrations','/integrations','Integrasi'],['reports','/reports','Laporan'],['users','/users','Pengguna']].filter(x=>allowed(user.role,x[0]));return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${esc(title)} | ${esc(APP_NAME)}</title><link rel="stylesheet" href="/assets/app.css?v=${ASSET_VERSION}"><link rel="stylesheet" href="/assets/growth.css?v=${ASSET_VERSION}"><script defer src="/assets/app.js?v=${ASSET_VERSION}"></script></head><body><div class="app"><aside class="sidebar"><a class="brand" href="/"><span class="brand-mark">SM</span><span><strong>STIFIn Mulia</strong><small>Growth OS</small></span></a><nav>${nav.map(x=>`<a class="nav ${active===x[0]?'active':''}" href="${x[1]}"${x[3]?' target="_blank" rel="noopener noreferrer"':''}>${x[2]}${x[3]?' ↗':''}</a>`).join('')}</nav><div class="foot"><a class="nav" href="/profile">Profil</a><form method="post" action="/logout"><input type="hidden" name="csrf" value="${s.csrf}"><button class="nav">Keluar</button></form></div></aside><main><header class="topbar"><button class="menu" data-menu>☰</button><div><small>Growth Operating System</small><h1>${esc(title)}</h1></div><div class="user"><span>${initials(user.name)}</span><div><strong>${esc(user.name)}</strong><small>${esc(user.role)}</small></div></div></header><section class="content">${flash?`<div class="flash">${esc(flash)}</div>`:''}${content}</section></main></div></body></html>`}

function starSenderWebWhatsAppUrl(){
  try{
    const target=new URL(String(process.env.STARSENDER_WEB_WHATSAPP_URL||'').trim());
    if(target.protocol!=='https:'||target.hostname!=='app.starsender.online'||!target.pathname.startsWith('/web-whatsapp/'))return '';
    return target.href;
  }catch{return ''}
}
function starSenderWebWhatsAppRoute(res,user,s){
  const target=starSenderWebWhatsAppUrl();
  if(target)return redirect(res,target);
  return html(res,503,layout(user,s,'WhatsApp Live','whatsapp-live',messageView('WhatsApp Live belum dikonfigurasi','Tambahkan STARSENDER_WEB_WHATSAPP_URL di Environment Variables Coolify, lalu lakukan Redeploy.')));
}
function dashboard(){const t=today(),statsData=[['Total Konten',state.content.length,'green'],['Lead Prioritas',state.leads.filter(x=>leadInsight(x).score>=70).length,'orange'],['Lead Masuk',state.leads.length,'blue'],['Booking',state.leads.filter(x=>x.status==='Booking').length,'green'],['Promotor Aktif',state.promoters.filter(x=>x.status==='Promotor aktif').length,'blue'],['Kampanye Aktif',state.campaigns.filter(x=>x.active).length,'orange']];const upcoming=state.content.filter(x=>x.plannedDate>=t).sort((a,b)=>a.plannedDate.localeCompare(b.plannedDate)).slice(0,7),follow=state.leads.filter(x=>x.nextFollowUp&&x.nextFollowUp<=t&&!['Tes selesai','Tidak dilanjutkan'].includes(x.status)).slice(0,7);return `<div class="stats">${statsData.map(x=>`<article class="stat ${x[2]}"><span>${x[0]}</span><strong>${x[1]}</strong><small>Data saat ini</small></article>`).join('')}</div><div class="grid two"><section class="panel"><div class="panel-head"><div><p class="eyebrow">AGENDA</p><h2>Konten Mendatang</h2></div><a href="/calendar">Buka kalender</a></div>${items(upcoming,'content')}</section><section class="panel"><div class="panel-head"><div><p class="eyebrow">TINDAK LANJUT</p><h2>Perlu Dihubungi</h2></div><a href="/crm">Buka Growth CRM</a></div>${items(follow,'leads')}</section></div><section class="panel"><p class="eyebrow">AKTIVITAS</p><h2>Aktivitas Terbaru</h2>${state.activity.length?`<div class="item-list">${state.activity.slice(0,12).map(x=>`<a><span>${dateShort(x.createdAt)}</span><div><strong>${esc(x.userName)} ${esc(x.action)} ${esc(x.subject)}</strong><small>${esc(x.detail||'')}</small></div></a>`).join('')}</div>`:empty('Aktivitas akan muncul setelah data diperbarui.')}</section>`}
function items(rows,key){return rows.length?`<div class="item-list">${rows.map(x=>`<a href="/${key}/${x.id}/edit"><span>${dateShort(x.plannedDate||x.nextFollowUp)}</span><div><strong>${esc(x.title||x.name)}</strong><small>${esc(x.pillar||x.need||x.type||'')}</small></div><span class="badge">${esc(x.status)}</span></a>`).join('')}</div>`:empty('Belum ada data terjadwal.')}
function listView(key,d,rows,total,q,st,page,pages,user,csrf){const edit=user.role!=='viewer';return `<section class="panel"><div class="panel-head wrap"><div><p class="eyebrow">DATA OPERASIONAL</p><h2>${d.label}</h2><small>${total} data ditemukan</small></div>${edit?`<a class="btn primary" href="/${key}/new">+ Tambah ${d.single}</a>`:''}</div><form class="filters"><input type="search" name="q" value="${esc(q)}" placeholder="Cari data"><select name="status"><option value="">Semua status</option>${(status[key]||[]).map(x=>`<option ${st===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn">Terapkan</button></form><div class="table-wrap"><table><thead><tr>${d.list.map(x=>`<th>${labels[x]||x}</th>`).join('')}<th>Aksi</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr>${d.list.map(k=>`<td>${cell(k,x[k])}</td>`).join('')}<td class="table-actions"><a href="/${key}/${x.id}/edit">${edit?'Edit':'Lihat'}</a>${key==='leads'&&x.phone?`<a href="/messages?lead=${x.id}">Pesan</a>`:''}${key==='promoters'&&x.stifinCode&&allowed(user.role,'integrations')?`<form method="post" action="/promoters/${x.id}/voucher"><input type="hidden" name="csrf" value="${csrf}"><button>Periksa voucher</button></form>`:''}${key==='templates'?`<button type="button" data-copy="${esc(x.body)}">Salin</button>`:''}${key==='campaigns'?`<button type="button" data-copy="${esc(`${process.env.APP_URL||'https://app.stifinmulia.com'}/go/${x.code}`)}">Salin Link</button><a target="_blank" href="/go/${encodeURIComponent(x.code)}">Tes</a>`:''}${edit?`<form method="post" action="/${key}/${x.id}/delete" data-confirm="Hapus data ini?"><input type="hidden" name="csrf" value="${csrf}"><button>Hapus</button></form>`:''}</td></tr>`).join(''):`<tr><td colspan="${d.list.length+1}">${empty('Belum ada data.')}</td></tr>`}</tbody></table></div>${pages>1?`<div class="pager">${page>1?`<a class="btn" href="/${key}?q=${encodeURIComponent(q)}&status=${encodeURIComponent(st)}&page=${page-1}">Sebelumnya</a>`:''}<span>Halaman ${page} dari ${pages}</span>${page<pages?`<a class="btn" href="/${key}?q=${encodeURIComponent(q)}&status=${encodeURIComponent(st)}&page=${page+1}">Berikutnya</a>`:''}</div>`:''}</section>`}
function formView(key,d,item,csrf,errors=[],readonly=false){return `<section class="panel narrow"><div class="panel-head"><div><p class="eyebrow">${item.id?'PERBARUI':'TAMBAH DATA'}</p><h2>${esc(item.title||item.name||item.participantName||item.situation||d.single)}</h2></div><a class="btn ghost" href="/${key}">Kembali</a></div>${errors.length?`<div class="alert bad"><ul>${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<form class="form-grid" method="post" action="/${key}${item.id?`/${item.id}`:''}"><input type="hidden" name="csrf" value="${csrf}">${d.fields.map(f=>field(f,item[f[0]],readonly)).join('')}${readonly?'':`<div class="form-actions"><button class="btn primary">Simpan Data</button><a class="btn" href="/${key}">Batal</a></div>`}</form></section>`}
function field(f,value,readonly){const[n,label,type='text',required,options]=f,dis=readonly?'disabled':'',req=required?'required':'',full=type==='textarea'||['body','caption','carousel','reels'].includes(n)?'full':'';if(type==='textarea')return `<label class="${full}">${label}<textarea name="${n}" rows="${['body','caption'].includes(n)?8:4}" ${req} ${dis}>${esc(value||'')}</textarea></label>`;if(type==='select')return `<label>${label}<select name="${n}" ${req} ${dis}><option value="">Pilih</option>${options.map(x=>`<option ${String(value||'')===x?'selected':''}>${x}</option>`).join('')}</select></label>`;if(type==='checkbox')return `<label class="check"><input type="checkbox" name="${n}" ${value?'checked':''} ${dis}> ${label}</label>`;return `<label class="${full}">${label}<input type="${type}" name="${n}" value="${esc(value||'')}" ${req} ${dis}></label>`}
function calendar(month){month=/^\d{4}-(0[1-9]|1[0-2])$/.test(month||'')?month:new Date().toISOString().slice(0,7);const[y,m]=month.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)),last=new Date(Date.UTC(y,m,0)),before=(first.getUTCDay()+6)%7,cells=[];for(let i=0;i<Math.ceil((before+last.getUTCDate())/7)*7;i++){const d=i-before+1;if(d<1||d>last.getUTCDate())cells.push('<div class="day muted-day"></div>');else{const iso=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,xs=state.content.filter(x=>x.plannedDate===iso);cells.push(`<div class="day"><b>${d}</b>${xs.slice(0,3).map(x=>`<a href="/content/${x.id}/edit">${esc(x.title)}</a>`).join('')}</div>`)}}const prev=new Date(Date.UTC(y,m-2,1)).toISOString().slice(0,7),next=new Date(Date.UTC(y,m,1)).toISOString().slice(0,7);return `<section class="panel"><div class="panel-head"><div><p class="eyebrow">RENCANA PUBLIKASI</p><h2>${month}</h2></div><div class="button-row"><a class="btn" href="/calendar?month=${prev}">Sebelumnya</a><a class="btn" href="/calendar?month=${next}">Berikutnya</a></div></div><div class="calendar"><div class="cal-head">${['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'].map(x=>`<span>${x}</span>`).join('')}</div><div class="cal-grid">${cells.join('')}</div></div></section>`}
function reports(){const group=(rows,k)=>Object.entries(rows.reduce((a,x)=>{const n=x[k]||'Belum diisi';a[n]=(a[n]||0)+1;return a},{})).map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value),bar=rows=>{const max=Math.max(1,...rows.map(x=>x.value));return rows.length?`<div class="bars">${rows.slice(0,10).map(x=>`<div><p><span>${esc(x.label)}</span><b>${x.value}</b></p><i style="width:${Math.max(3,x.value/max*100)}%"></i></div>`).join('')}</div>`:empty('Belum ada data.')};const bookings=state.leads.filter(x=>['Booking','Tes selesai','Tindak lanjut'].includes(x.status)).length,tests=state.leads.filter(x=>x.status==='Tes selesai').length,sent=state.messages.filter(x=>x.status==='Terkirim').length,failed=state.messages.filter(x=>x.status==='Gagal').length,totalClicks=state.campaigns.reduce((n,x)=>n+Number(x.clicks||0),0),campaignLeads=state.campaigns.reduce((n,x)=>n+Number(x.leads||0),0);return `<div class="stats"><article class="stat"><span>Rasio booking</span><strong>${pct(state.leads.length?bookings/state.leads.length:0)}</strong></article><article class="stat blue"><span>Rasio kehadiran</span><strong>${pct(bookings?tests/bookings:0)}</strong></article><article class="stat orange"><span>Konversi kampanye</span><strong>${pct(totalClicks?campaignLeads/totalClicks:0)}</strong></article><article class="stat"><span>Pesan terkirim</span><strong>${sent}</strong></article><article class="stat orange"><span>Pesan gagal</span><strong>${failed}</strong></article><article class="stat blue"><span>Promotor API</span><strong>${state.promoters.filter(x=>x.source==='STIFIn API').length}</strong></article></div><div class="grid three"><section class="panel"><h2>Konten per Pilar</h2>${bar(group(state.content,'pillar'))}</section><section class="panel"><h2>Lead per Sumber</h2>${bar(group(state.leads,'source'))}</section><section class="panel"><h2>Kampanye per Kanal</h2>${bar(group(state.campaigns,'channel'))}</section></div><section class="panel"><h2>Unduh Data</h2><div class="button-row"><a class="btn" href="/export/content.csv">Konten CSV</a><a class="btn" href="/export/leads.csv">Lead CSV</a><a class="btn" href="/export/promoters.csv">Promotor CSV</a><a class="btn" href="/export/referrals.csv">Rujukan CSV</a><a class="btn" href="/export/campaigns.csv">Kampanye CSV</a><a class="btn primary" href="/backup.json">Cadangan lengkap</a></div></section>`}

function leadInsight(lead){
  let score=0;
  if(lead.phone)score+=10;if(lead.city)score+=5;if(lead.need)score+=10;if(lead.consentWhatsApp==='Ya')score+=15;
  score+=({'Segera':25,'1–4 minggu':18,'1–3 bulan':10,'Masih mencari informasi':4}[lead.urgency]||0);
  score+=({'Siap':20,'Perlu diskusi':10,'Belum siap':2}[lead.budgetReady]||0);
  score+=({'Baru':2,'Sudah dihubungi':8,'Terkualifikasi':15,'Konsultasi':22,'Booking':30,'Tes selesai':35,'Tindak lanjut':25}[lead.status]||0);
  score=Math.min(100,score);const temperature=score>=70?'Panas':score>=40?'Hangat':'Dingin';
  let action='Lengkapi kebutuhan dan domisili';
  if(lead.status==='Booking')action='Konfirmasi jadwal dan pembayaran';else if(lead.status==='Tes selesai')action='Kirim tindak lanjut hasil tes';else if(lead.consentWhatsApp!=='Ya')action='Minta persetujuan komunikasi';else if(lead.nextFollowUp&&lead.nextFollowUp<=today())action='Hubungi hari ini';else if(score>=70)action='Prioritaskan konsultasi';else if(score>=40)action='Kirim edukasi yang relevan';
  return {score,temperature,action};
}

function crmRoute(req,res,user,s){
  if(req.method==='POST'){
    if(user.role==='viewer')return html(res,403,layout(user,s,'Akses ditolak','crm',messageView('Akses tidak tersedia','Akun viewer hanya dapat membaca data.')));
    const lead=state.leads.find(x=>x.id===Number(req.body.leadId)),next=String(req.body.status||'');
    if(lead&&status.leads.includes(next)){update('leads',lead.id,{status:next,nextFollowUp:String(req.body.nextFollowUp||lead.nextFollowUp||'')});activity(user,'memindahkan tahap lead',lead.name,next)}
    return redirect(res,'/crm');
  }
  if(req.method!=='GET')return text(res,405,'Method not allowed');
  const stages=status.leads.filter(x=>!['Belum siap','Tidak dilanjutkan'].includes(x));
  const cards=lead=>{const i=leadInsight(lead);return `<article class="lead-card"><div class="lead-score ${i.temperature.toLowerCase()}"><b>${i.score}</b><span>${i.temperature}</span></div><h3>${esc(lead.name)}</h3><p>${esc(lead.city||'Domisili belum diisi')} · ${esc(lead.type||'Lead')}</p><small>${esc(lead.need||'Kebutuhan belum dicatat')}</small><div class="next-action">${esc(i.action)}</div><div class="card-actions"><a href="/messages?lead=${lead.id}">Pesan</a><a href="/leads/${lead.id}/edit">Detail</a></div>${user.role!=='viewer'?`<form method="post" class="stage-form"><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="leadId" value="${lead.id}"><select name="status">${status.leads.map(x=>`<option ${x===lead.status?'selected':''}>${x}</option>`).join('')}</select><input type="date" name="nextFollowUp" value="${esc(lead.nextFollowUp||'')}"><button class="btn">Simpan</button></form>`:''}</article>`};
  const priority=[...state.leads].map(x=>({...x,...leadInsight(x)})).sort((a,b)=>b.score-a.score).slice(0,5);
  return html(res,200,layout(user,s,'Growth CRM','crm',`<div class="stats"><article class="stat orange"><span>Lead prioritas</span><strong>${state.leads.filter(x=>leadInsight(x).score>=70).length}</strong><small>Skor 70–100</small></article><article class="stat blue"><span>Perlu follow-up</span><strong>${state.leads.filter(x=>x.nextFollowUp&&x.nextFollowUp<=today()&&!['Tes selesai','Tidak dilanjutkan'].includes(x.status)).length}</strong><small>Sampai hari ini</small></article><article class="stat"><span>Dengan izin WA</span><strong>${state.leads.filter(x=>x.consentWhatsApp==='Ya').length}</strong><small>Siap ditindaklanjuti</small></article><article class="stat blue"><span>Booking</span><strong>${state.leads.filter(x=>x.status==='Booking').length}</strong><small>Dalam pipeline</small></article></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">NEXT BEST ACTION</p><h2>Prioritas Hari Ini</h2></div><a class="btn primary" href="/leads/new">+ Tambah Lead</a></div>${priority.length?`<div class="priority-grid">${priority.map(x=>`<a href="/messages?lead=${x.id}"><b>${x.score}</b><span><strong>${esc(x.name)}</strong><small>${esc(x.action)}</small></span></a>`).join('')}</div>`:empty('Lead akan muncul setelah data ditambahkan.')}</section><section class="panel kanban-panel"><div class="panel-head"><div><p class="eyebrow">PIPELINE</p><h2>Perjalanan Calon Peserta</h2></div><a href="/leads">Tampilan tabel</a></div><div class="kanban">${stages.map(stage=>{const rows=state.leads.filter(x=>x.status===stage);return `<div class="kanban-column"><header><b>${esc(stage)}</b><span>${rows.length}</span></header>${rows.length?rows.map(cards).join(''):empty('Kosong')}</div>`}).join('')}</div></section>`));
}

function generateCopy(source,audience,goal){
  const title=source.title||'Memahami diri melalui STIFIn',hook=source.hook||`Pernah bertanya mengapa cara setiap orang memahami masalah bisa berbeda?`,problem=source.problem||'Banyak orang memaksakan cara yang tidak sesuai dengan kecenderungan dirinya.',core=source.core||source.caption||'STIFIn membantu pembaca mengenali kecenderungan mesin kecerdasan sebagai bahan refleksi dan pengembangan diri.',action=source.action||'Mulailah dengan memahami hasil tes bersama promotor yang dapat menjelaskan secara utuh.',cta=source.cta||'Konsultasikan kebutuhan Anda bersama STIFIn Mulia.',who=audience||source.audience||'orang tua, mahasiswa, pendidik, dan profesional';
  return {headline:`${title}: Jawaban Praktis untuk ${who}`,caption:`${hook}\n\n${problem}\n\n${core}\n\n${action}\n\n${cta}`,whatsapp:`Assalamu’alaikum. Kami sedang membagikan materi “${title}” untuk ${who}.\n\n${hook}\n\n${core}\n\nJika berkenan, kami dapat membantu menjelaskan kaitannya dengan kebutuhan Anda.`,carousel:`Slide 1 — ${hook}\nSlide 2 — Situasi: ${problem}\nSlide 3 — Mengapa hal ini sering terjadi?\nSlide 4 — Sudut pandang STIFIn: ${core}\nSlide 5 — Hal yang perlu dihindari\nSlide 6 — Langkah praktis: ${action}\nSlide 7 — ${cta}`,reels:`HOOK (0–3 detik): ${hook}\nMASALAH (4–10 detik): ${problem}\nPENJELASAN (11–30 detik): ${core}\nLANGKAH (31–42 detik): ${action}\nCTA (43–50 detik): ${cta}`,seo:`Judul: ${title}\nTujuan pencarian: ${goal||'Edukasi dan konsultasi'}\nPembaca: ${who}\nH1: ${title}\nH2: Masalah yang sering dialami\nH2: Cara melihat masalah melalui perspektif STIFIn\nH2: Langkah praktis setelah memahami kecenderungan diri\nH2: Kapan tes STIFIn dibutuhkan\nH2: Konsultasi dan layanan wilayah`};
}

