  update('campaigns',campaign.id,{clicks:Number(campaign.clicks||0)+1});const ip=String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'').split(',')[0];insert('campaignEvents',{campaignId:campaign.id,code:campaign.code,event:'click',ipHash:crypto.createHash('sha256').update(`${state.meta.appKey}:${ip}`).digest('hex').slice(0,20),referrer:String(req.headers.referer||'').slice(0,300),userAgent:String(req.headers['user-agent']||'').slice(0,300)});
