function chatKey(type,address){return `${type==='group'?'group':'personal'}:${String(address||'').replace(/\s+/g,'').toLowerCase()}`}
function migrateConversations(){
  for(const message of state.messages){
    const type=message.chatType==='group'||message.isGroup?'group':'personal',address=message.groupId||message.phone;
    if(!address)continue;message.chatType=type;message.chatKey??=chatKey(type,address);
    upsertConversation({type,address,key:message.chatKey,name:message.name,leadId:message.leadId,message:message.message,direction:message.direction,at:message.createdAt},{saveNow:false,countUnread:false});
  }
}
function upsertConversation(data,options={}){
  const key=data.key||chatKey(data.type,data.address);let conversation=state.conversations.find(x=>x.key===key),now=data.at||new Date().toISOString();
  if(!conversation){conversation={id:state.meta.next.conversations++,key,type:data.type==='group'?'group':'personal',name:data.name||data.address,address:data.address,leadId:Number(data.leadId)||0,labels:[],unread:0,needsReply:false,createdAt:now};state.conversations.push(conversation)}
  conversation.name=data.name||conversation.name||data.address;conversation.address=data.address||conversation.address;conversation.leadId=Number(data.leadId)||conversation.leadId||0;conversation.lastMessage=String(data.message||conversation.lastMessage||'').slice(0,4000);conversation.lastMessageAt=now;conversation.updatedAt=now;
  if(data.direction==='Masuk'){if(options.countUnread!==false)conversation.unread=Number(conversation.unread||0)+1;conversation.needsReply=true}else if(data.direction==='Keluar'){conversation.needsReply=false}
  if(options.saveNow!==false)save();return conversation;
}

async function syncGroupsRoute(req,res,user,s){
  if(user.role==='viewer')return html(res,403,layout(user,s,'Akses ditolak','messages',messageView('Akses tidak tersedia','Akun viewer hanya dapat membaca data.')));
  try{const rows=await fetchWhatsAppGroups();let created=0,updated=0;for(const row of rows){let group=state.groups.find(x=>x.groupId===row.groupId||(x.name===row.name&&!row.groupId));if(group){Object.assign(group,row,{syncedAt:new Date().toISOString()});updated++}else{group={id:state.meta.next.groups++,...row,syncedAt:new Date().toISOString()};state.groups.push(group);created++}upsertConversation({type:'group',address:group.groupId||group.name,name:group.name},{saveNow:false,countUnread:false})}save();activity(user,'menyinkronkan','grup WhatsApp',`${created} baru, ${updated} diperbarui`);return redirect(res,`/messages?notice=${encodeURIComponent(`${rows.length} grup berhasil disinkronkan`)}`)}catch(error){return redirect(res,`/messages?error=${encodeURIComponent(error.message||'Sinkronisasi grup gagal')}`)}
}

function broadcastRecipients(){
  const rows=[],seen=new Set();
  for(const group of state.groups){const address=String(group.groupId||group.name||'').trim(),key=chatKey('group',address);if(!address||seen.has(key))continue;seen.add(key);rows.push({key,type:'group',address,name:group.name||address,detail:`${group.participants||0} anggota`})}
  for(const lead of state.leads){const address=String(lead.phone||'').trim(),key=chatKey('personal',address);if(!address||lead.consentWhatsApp!=='Ya'||seen.has(key))continue;seen.add(key);rows.push({key,type:'personal',address,name:lead.name||address,detail:lead.city||lead.status||'Lead',leadId:lead.id})}
  return rows;
}

async function broadcastsRoute(req,res,user,s){
  if(user.role==='viewer')return html(res,403,layout(user,s,'Akses ditolak','broadcasts',messageView('Akses tidak tersedia','Akun viewer hanya dapat membaca data.')));
  const url=new URL(req.url,`http://${req.headers.host||'localhost'}`),directory=broadcastRecipients(),directoryMap=new Map(directory.map(x=>[x.key,x]));
  let preset=state.recipientPresets.find(x=>x.id===Number(url.searchParams.get('preset')))||null,selectedKeys=new Set(preset?.recipientKeys||[]),notice=String(url.searchParams.get('notice')||''),error='',presetName=preset?.name||'';
  if(req.method==='POST'){
    const action=String(req.body.action||''),submitted=[...new Set(values(req.body.recipientKeys).filter(x=>directoryMap.has(x)))];selectedKeys=new Set(submitted);presetName=String(req.body.presetName||'').trim();
    if(action==='deletePreset'){
      const target=state.recipientPresets.find(x=>x.id===Number(req.body.presetId));if(target){remove('recipientPresets',target.id);activity(user,'menghapus preset penerima',target.name)}return redirect(res,'/broadcasts?notice=Preset+penerima+berhasil+dihapus');
    }
    if(action==='savePreset'){
      if(!presetName)error='Nama preset wajib diisi.';else if(!submitted.length)error='Pilih minimal satu penerima untuk preset.';else{const existing=state.recipientPresets.find(x=>x.id===Number(req.body.presetId));const record={name:presetName,recipientKeys:submitted,recipientCount:submitted.length,createdBy:user.name};preset=existing?update('recipientPresets',existing.id,record):insert('recipientPresets',record);activity(user,existing?'memperbarui preset penerima':'membuat preset penerima',presetName,`${submitted.length} penerima`);return redirect(res,`/broadcasts?preset=${preset.id}&notice=Preset+penerima+berhasil+disimpan`)}
    }
    if(action==='sendBroadcast'){
      const template=state.templates.find(x=>x.id===Number(req.body.templateId));let message=String(req.body.message||template?.body||'').trim(),file='';
      if(!submitted.length)error='Pilih minimal satu grup atau kontak pribadi.';
      if(!error&&req.body.imageUpload&&!req.body.imageData)error='Gambar belum selesai diproses. Pilih ulang gambar, tunggu pratinjau muncul, lalu kirim.';
      if(!error&&!message&&!req.body.imageData)error='Isi pesan atau pilih gambar sebelum mengirim.';
      if(!error&&submitted.length>50)error='Satu pengiriman dibatasi maksimal 50 penerima.';
      try{if(!error&&req.body.imageData){const filename=saveImageData(req.body.imageData);file=publicMediaUrl(req,filename)}}catch(e){error=e.message}
      if(!error){let sent=0,failed=0;const failures=[],delay=Math.max(0,Math.min(5000,Number(process.env.BROADCAST_DELAY_MS??500)));
        for(let index=0;index<submitted.length;index++){
          const recipient=directoryMap.get(submitted[index]),personalized=message.replaceAll('{nama}',recipient.name),summary=personalized||'[Gambar]';
          try{const result=recipient.type==='group'?await sendStarSenderGroup({group:recipient.address,message:personalized,file}):await sendStarSender({phone:recipient.address,message:personalized,file});insert('messages',{leadId:recipient.leadId||0,name:recipient.name,phone:recipient.type==='personal'?recipient.address:'',groupId:recipient.type==='group'?recipient.address:'',message:summary,file,direction:'Keluar',chatType:recipient.type,chatKey:recipient.key,channel:'StarSender Massal',status:'Terkirim',externalId:result.externalId,sentBy:user.name});upsertConversation({type:recipient.type,address:recipient.address,key:recipient.key,name:recipient.name,leadId:recipient.leadId,message:summary,direction:'Keluar'},{saveNow:false});sent++}
          catch(e){insert('messages',{leadId:recipient.leadId||0,name:recipient.name,phone:recipient.type==='personal'?recipient.address:'',groupId:recipient.type==='group'?recipient.address:'',message:summary,file,direction:'Keluar',chatType:recipient.type,chatKey:recipient.key,channel:'StarSender Massal',status:'Gagal',error:String(e.message||e).slice(0,250),sentBy:user.name});failed++;failures.push(`${recipient.name}: ${String(e.message||e).slice(0,120)}`)}
          if(delay&&index<submitted.length-1)await wait(delay);
        }
        insert('broadcastRuns',{presetId:Number(req.body.presetId)||0,presetName:presetName||preset?.name||'',recipientCount:submitted.length,sent,failed,message:message.slice(0,500),file,failures,sentBy:user.name});activity(user,'mengirim pesan massal',`${submitted.length} penerima`,`${sent} terkirim, ${failed} gagal`);notice=`Pengiriman selesai: ${sent} berhasil${failed?` dan ${failed} gagal`:''}.`;
      }
    }
  }else if(req.method!=='GET')return text(res,405,'Method not allowed');
  const recipientGroup=(type,title)=>{const rows=directory.filter(x=>x.type===type);return `<section class="recipient-group"><header><div><strong>${title}</strong><small>${rows.length} tersedia</small></div><button type="button" class="link-button" data-check-type="${type}">Pilih semua</button></header>${rows.length?rows.map(x=>`<label><input type="checkbox" name="recipientKeys" value="${esc(x.key)}" data-recipient-type="${type}" ${selectedKeys.has(x.key)?'checked':''}><span><strong>${esc(x.name)}</strong><small>${esc(x.detail)}</small></span></label>`).join(''):empty(type==='group'?'Sinkronkan grup dari Communication Center terlebih dahulu.':'Belum ada lead yang memberikan izin WhatsApp.')}</section>`};
  const presets=state.recipientPresets.length?state.recipientPresets.map(x=>`<article><a href="/broadcasts?preset=${x.id}"><strong>${esc(x.name)}</strong><small>${x.recipientCount||x.recipientKeys?.length||0} penerima</small></a><form method="post" data-confirm="Hapus preset ini?"><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="presetId" value="${x.id}"><button class="link-button danger-text" name="action" value="deletePreset">Hapus</button></form></article>`).join(''):empty('Belum ada preset penerima.');
  const runs=state.broadcastRuns.length?state.broadcastRuns.slice(-8).reverse().map(x=>`<article><span>${dateTimeShort(x.createdAt)}</span><div><strong>${esc(x.presetName||`${x.recipientCount} penerima`)}</strong><small>${x.sent||0} terkirim · ${x.failed||0} gagal${x.file?' · gambar':''}</small></div></article>`).join(''):empty('Belum ada pengiriman massal.');
  const content=`${notice?`<div class="flash">${esc(notice)}</div>`:''}${error?`<div class="alert bad">${esc(error)}</div>`:''}<div class="broadcast-layout"><section class="panel broadcast-main"><div class="panel-head"><div><p class="eyebrow">PENERIMA TERSIMPAN</p><h2>Kirim ke Banyak Grup dan Kontak</h2></div><span class="badge">Maksimal 50 penerima</span></div><p class="muted">Kontak pribadi yang tampil hanya lead dengan izin WhatsApp “Ya”. Gunakan <code>{nama}</code> untuk personalisasi nama penerima.</p><form method="post" data-broadcast-form><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="presetId" value="${preset?.id||''}"><div class="recipient-columns">${recipientGroup('group','Grup WhatsApp')}${recipientGroup('personal','Kontak Pribadi')}</div><div class="broadcast-compose"><label>Nama preset<input name="presetName" value="${esc(presetName)}" placeholder="Contoh: Promotor Jawa Barat"></label><label>Template pesan<select name="templateId" data-message-template><option value="">Tanpa template</option>${state.templates.filter(x=>x.active).map(x=>`<option value="${x.id}" data-message="${esc(x.body)}">${esc(x.code)} · ${esc(x.situation)}</option>`).join('')}</select></label><label class="full">Pesan atau caption<textarea name="message" rows="5" placeholder="Tulis pesan. Boleh dikosongkan jika hanya mengirim gambar.">${esc(req.body?.message||'')}</textarea></label><label class="full image-upload">Gambar JPG, PNG, atau WebP<input type="file" name="imageUpload" accept="image/jpeg,image/png,image/webp" data-image-file><input type="hidden" name="imageData" data-image-data><span data-image-status>Maksimal 4 MB.</span><img data-image-preview alt="Pratinjau gambar" hidden></label></div><div class="form-actions"><button class="btn" name="action" value="savePreset">Simpan Preset</button><button class="btn primary" name="action" value="sendBroadcast" data-broadcast-send>Kirim Sekarang</button></div></form></section><aside><section class="panel"><p class="eyebrow">PRESET</p><h2>Daftar Penerima</h2><div class="preset-list">${presets}</div></section><section class="panel section-gap"><p class="eyebrow">RIWAYAT</p><h2>Pengiriman Terakhir</h2><div class="broadcast-runs">${runs}</div></section></aside></div>`;
  return html(res,error?422:200,layout(user,s,'Kirim Massal','broadcasts',content));
}

async function messagesRoute(req,res,user,s){
  const url=new URL(req.url,`http://${req.headers.host||'localhost'}`),q=String(url.searchParams.get('q')||'').toLowerCase(),filter=String(url.searchParams.get('filter')||'all');let notice=String(url.searchParams.get('notice')||''),error=String(url.searchParams.get('error')||'');
  let selectedLead=state.leads.find(x=>x.id===Number(url.searchParams.get('lead')))||null,selectedKey=String(url.searchParams.get('chat')||'');
  if(selectedLead&&!selectedKey){selectedKey=chatKey('personal',selectedLead.phone);if(!state.conversations.some(x=>x.key===selectedKey))upsertConversation({type:'personal',address:selectedLead.phone,name:selectedLead.name,leadId:selectedLead.id},{countUnread:false})}
  if(req.method==='POST'){
    if(user.role==='viewer')return html(res,403,layout(user,s,'Akses ditolak','messages',messageView('Akses tidak tersedia','Akun viewer hanya dapat membaca data.')));
    selectedKey=String(req.body.chatKey||selectedKey);let conversation=state.conversations.find(x=>x.key===selectedKey)||null;
    if(req.body.action==='labels'&&conversation){conversation.labels=String(req.body.labels||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,12);save();return redirect(res,`/messages?chat=${encodeURIComponent(conversation.key)}&notice=Label+berhasil+disimpan`)}
    if(req.body.action==='note'&&conversation){const note=String(req.body.note||'').trim();if(note)insert('conversationNotes',{conversationKey:conversation.key,body:note,userName:user.name});return redirect(res,`/messages?chat=${encodeURIComponent(conversation.key)}&notice=Catatan+internal+disimpan`)}
    if(req.body.action==='markRead'&&conversation){conversation.unread=0;save();return redirect(res,`/messages?chat=${encodeURIComponent(conversation.key)}`)}
    selectedLead=state.leads.find(x=>x.id===Number(req.body.leadId))||state.leads.find(x=>x.id===Number(conversation?.leadId))||null;
    const template=state.templates.find(x=>x.id===Number(req.body.templateId)),type=conversation?.type||String(req.body.targetType||'personal'),address=String(conversation?.address||selectedLead?.phone||req.body.phone||req.body.groupId||'').trim(),name=String(conversation?.name||selectedLead?.name||req.body.name||address).trim();
    const message=String(req.body.message||template?.body||'').replaceAll('{nama}',name).trim();let file='';
    if(req.body.imageUpload&&!req.body.imageData)error='Gambar belum selesai diproses. Pilih ulang gambar, tunggu sampai siap, lalu kirim.';
    else if(!address||(!message&&!req.body.imageData))error=type==='group'?'Grup serta pesan atau gambar wajib dipilih.':'Nomor WhatsApp serta pesan atau gambar wajib diisi.';
    else if(req.body.action==='send'&&type!=='group'&&selectedLead?.consentWhatsApp!=='Ya')error='Pengiriman otomatis memerlukan izin WhatsApp “Ya” pada data lead.';
    else if(req.body.action==='open'&&type==='group')error='Grup tidak dapat dibuka melalui tautan WhatsApp manual.';
    else if(req.body.action==='open'&&req.body.imageData)error='Gambar hanya dapat dikirim melalui tombol Kirim dengan integrasi StarSender.';
    try{if(!error&&req.body.imageData){const filename=saveImageData(req.body.imageData);file=publicMediaUrl(req,filename)}}catch(e){error=e.message}
    if(!error&&req.body.action==='open'){insert('messages',{leadId:selectedLead?.id||0,name,phone:address,message,direction:'Keluar',chatType:'personal',chatKey:chatKey('personal',address),channel:'WhatsApp manual',status:'Dibuka',sentBy:user.name});upsertConversation({type:'personal',address,name,leadId:selectedLead?.id,message,direction:'Keluar'});activity(user,'membuka pesan WhatsApp untuk',name||address);return redirect(res,wa(address,message))}
    else if(!error){try{const sent=type==='group'?await sendStarSenderGroup({group:address,message,file}):await sendStarSender({phone:address,message,file}),key=chatKey(type,address),summary=message||'[Gambar]';insert('messages',{leadId:selectedLead?.id||0,name,phone:type==='group'?'':address,groupId:type==='group'?address:'',message:summary,file,direction:'Keluar',chatType:type,chatKey:key,channel:'StarSender',status:'Terkirim',externalId:sent.externalId,sentBy:user.name});upsertConversation({type,address,key,name,leadId:selectedLead?.id,message:summary,direction:'Keluar'});activity(user,'mengirim pesan kepada',name||address,type==='group'?'Grup StarSender':'StarSender');notice=file?'Gambar berhasil diteruskan ke StarSender.':'Pesan berhasil diteruskan ke StarSender.';selectedKey=key}catch(e){insert('messages',{leadId:selectedLead?.id||0,name,phone:address,message:message||'[Gambar]',file,direction:'Keluar',chatType:type,chatKey:chatKey(type,address),channel:'StarSender',status:'Gagal',error:String(e.message||e).slice(0,250),sentBy:user.name});error=`Pesan belum terkirim: ${e.message}`}}
  }else if(req.method!=='GET')return text(res,405,'Method not allowed');
  let conversations=[...state.conversations].sort((a,b)=>String(b.lastMessageAt||b.updatedAt||'').localeCompare(String(a.lastMessageAt||a.updatedAt||'')));
  if(q)conversations=conversations.filter(x=>[x.name,x.address,x.lastMessage,...(x.labels||[])].some(v=>String(v||'').toLowerCase().includes(q)));
  if(filter==='unread')conversations=conversations.filter(x=>Number(x.unread)>0);if(filter==='reply')conversations=conversations.filter(x=>x.needsReply);if(filter==='group')conversations=conversations.filter(x=>x.type==='group');if(filter==='personal')conversations=conversations.filter(x=>x.type!=='group');
  let selected=state.conversations.find(x=>x.key===selectedKey)||conversations[0]||null;if(selected)selectedKey=selected.key;
  const thread=selected?state.messages.filter(x=>x.chatKey===selected.key||(!x.chatKey&&selected.type==='personal'&&chatKey('personal',x.phone)===selected.key)).slice(-100):[],notes=selected?state.conversationNotes.filter(x=>x.conversationKey===selected.key).slice(-20):[],ss=starSenderConfig();
  const list=conversations.length?conversations.map(x=>`<a class="conversation-item ${selected?.key===x.key?'active':''}" href="/messages?chat=${encodeURIComponent(x.key)}&filter=${encodeURIComponent(filter)}"><span class="chat-avatar ${x.type==='group'?'group':''}">${x.type==='group'?'G':esc(initials(x.name))}</span><span><strong>${esc(x.name||x.address)}</strong><small>${esc(String(x.lastMessage||'Belum ada pesan').slice(0,75))}</small><i>${(x.labels||[]).slice(0,2).map(label=>`<b>${esc(label)}</b>`).join('')}</i></span>${x.unread?`<em>${x.unread}</em>`:''}</a>`).join(''):empty('Belum ada percakapan.');
  const bubbles=thread.length?thread.map(x=>{const media=mediaHref(x.file);return `<article class="bubble ${x.direction==='Keluar'?'out':'in'}">${media?`<a class="bubble-media" href="${esc(media)}" target="_blank" rel="noopener"><img src="${esc(media)}" alt="Gambar WhatsApp"></a>`:''}<p>${esc(x.message||'[Lampiran]')}</p><small>${esc(x.sentBy||x.name||'Webhook')} · ${esc(dateTimeShort(x.createdAt))}</small></article>`}).join(''):empty('Belum ada pesan pada percakapan ini.');
  const composer=selected&&user.role!=='viewer'?`<form method="post" class="chat-composer" data-image-form><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="chatKey" value="${esc(selected.key)}"><select name="templateId" data-message-template><option value="">Tulis pesan</option>${state.templates.filter(x=>x.active).map(x=>`<option value="${x.id}" data-message="${esc(x.body)}">${esc(x.code)} · ${esc(x.situation)}</option>`).join('')}</select><textarea name="message" rows="3" placeholder="Tulis balasan atau caption...">${esc(req.body?.message||'')}</textarea><label class="composer-image" title="Tambahkan gambar"><span>+ Gambar</span><input type="file" name="imageUpload" accept="image/jpeg,image/png,image/webp" data-image-file><input type="hidden" name="imageData" data-image-data></label><div><small data-image-status></small><button class="btn primary" name="action" value="send">Kirim</button>${selected.type!=='group'?`<button class="btn" name="action" value="open">Buka WhatsApp</button>`:''}</div></form>`:'';
  const details=selected?`<section class="chat-details"><span class="chat-avatar large ${selected.type==='group'?'group':''}">${selected.type==='group'?'G':esc(initials(selected.name))}</span><h3>${esc(selected.name)}</h3><p>${esc(selected.address)}</p><span class="badge">${selected.type==='group'?'Grup WhatsApp':'Percakapan pribadi'}</span>${selected.leadId?`<a class="btn" href="/leads/${selected.leadId}/edit">Buka data lead</a>`:''}${user.role!=='viewer'?`<form method="post"><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="chatKey" value="${esc(selected.key)}"><label>Label CRM<input name="labels" value="${esc((selected.labels||[]).join(', '))}" placeholder="Lead Baru, Siap Booking"></label><button class="btn" name="action" value="labels">Simpan label</button></form><form method="post"><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="chatKey" value="${esc(selected.key)}"><label>Catatan internal<textarea name="note" rows="3" placeholder="Tidak dikirim ke WhatsApp"></textarea></label><button class="btn" name="action" value="note">Tambah catatan</button></form>`:''}<div class="internal-notes">${notes.map(n=>`<p>${esc(n.body)}<small>${esc(n.userName)} · ${esc(dateTimeShort(n.createdAt))}</small></p>`).join('')}</div></section>`:`<section class="chat-details">${empty('Pilih percakapan.')}</section>`;
  return html(res,error?422:200,layout(user,s,'Communication Center','messages',`${notice?`<div class="flash">${esc(notice)}</div>`:''}${error?`<div class="alert bad">${esc(error)}</div>`:''}<section class="communication-toolbar"><form><input type="search" name="q" value="${esc(url.searchParams.get('q')||'')}" placeholder="Cari kontak, grup, pesan, atau label"><select name="filter"><option value="all">Semua</option><option value="unread" ${filter==='unread'?'selected':''}>Belum dibaca</option><option value="reply" ${filter==='reply'?'selected':''}>Belum dibalas</option><option value="personal" ${filter==='personal'?'selected':''}>Pribadi</option><option value="group" ${filter==='group'?'selected':''}>Grup</option></select><button class="btn">Terapkan</button></form>${user.role!=='viewer'?`<form method="post" action="/messages/sync-groups"><input type="hidden" name="csrf" value="${s.csrf}"><button class="btn">Sinkronkan Grup</button></form>`:''}<span class="badge">StarSender ${ss.enabled&&ss.hasApiKey?'siap':'belum aktif'}</span></section><section class="communication-center"><aside class="conversation-list">${list}</aside><main class="thread-panel">${selected?`<header><div><h2>${esc(selected.name)}</h2><small>${selected.needsReply?'Perlu dibalas':'Percakapan ditangani'} · ${selected.unread||0} belum dibaca</small></div>${selected.unread&&user.role!=='viewer'?`<form method="post"><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="chatKey" value="${esc(selected.key)}"><button class="btn" name="action" value="markRead">Tandai dibaca</button></form>`:''}</header>`:''}<div class="message-thread">${bubbles}</div>${composer}</main>${details}</section>`));
}

async function starSenderWebhook(req,res,pathname){
  if(req.method!=='POST')return text(res,405,'Method not allowed');
  const configured=String(process.env.STARSENDER_WEBHOOK_SECRET||''),provided=pathname.split('/').pop()||'';
  if(!configured||!safe(provided,configured))return json(res,404,{ok:false});
  try{const payload=await jsonBody(req),event=sanitizeStarSenderWebhook(payload),type=event.isGroup||event.chatType==='group'?'group':'personal',address=type==='group'?(event.address||event.phone):event.phone,signature=crypto.createHash('sha256').update(`${event.externalId}|${address}|${event.sourceTimestamp}|${event.message}|${event.isMe}`).digest('hex');if(state.webhookEvents.some(x=>x.signature===signature))return json(res,200,{ok:true,duplicate:true});insert('webhookEvents',{...event,signature});if((event.message||event.file)&&address){const normalized=String(event.phone).replace(/\D/g,'').replace(/^62/,'0'),lead=type==='personal'?state.leads.find(x=>String(x.phone||'').replace(/\D/g,'').replace(/^62/,'0')===normalized):null,direction=event.isMe?'Keluar':'Masuk',key=chatKey(type,address),syncedGroup=type==='group'?state.groups.find(x=>x.groupId===address):null,name=lead?.name||syncedGroup?.name||event.pushName||address;insert('messages',{leadId:lead?.id||0,name,phone:type==='personal'?event.phone:'',groupId:type==='group'?address:'',message:event.message,file:event.file,quotedMessage:event.quotedMessage,direction,chatType:type,chatKey:key,channel:'StarSender',status:direction==='Masuk'?'Diterima':'Terkirim',externalId:event.externalId,device:event.device,sentBy:'Webhook'});upsertConversation({type,address,key,name,leadId:lead?.id,message:event.message||'[Lampiran]',direction,at:event.receivedAt});if(lead)update('leads',lead.id,direction==='Masuk'?{lastInboundAt:event.receivedAt}:{lastContacted:event.receivedAt.slice(0,10)})}return json(res,200,{ok:true})}catch(e){return json(res,e.statusCode||400,{ok:false})}
}
function profileForm(user,csrf,error='',success=''){return `<section class="panel narrow"><p class="eyebrow">AKUN</p><h2>Profil dan Keamanan</h2>${error?`<div class="alert bad">${esc(error)}</div>`:''}${success?`<div class="flash">${esc(success)}</div>`:''}<form method="post" class="form-grid"><input type="hidden" name="csrf" value="${csrf}"><label>Nama<input name="name" value="${esc(user.name)}" required></label><label>Email<input value="${esc(user.email)}" disabled></label><label>Password saat ini<input type="password" name="currentPassword"></label><label>Password baru<input type="password" name="newPassword" minlength="10"></label><label>Ulangi password baru<input type="password" name="confirmPassword" minlength="10"></label><div class="form-actions"><button class="btn primary">Simpan Profil</button></div></form></section>`}
function messageView(t,p){return `<section class="panel narrow"><h2>${esc(t)}</h2><p>${esc(p)}</p><a class="btn" href="/">Kembali ke Dashboard</a></section>`}

async function body(req,limit=1_500_000){const chunks=[];let size=0;for await(const c of req){size+=c.length;if(size>limit){const e=new Error('too large');e.statusCode=413;throw e}chunks.push(c)}const result={};for(const[key,value]of new URLSearchParams(Buffer.concat(chunks).toString()))result[key]===undefined?result[key]=value:Array.isArray(result[key])?result[key].push(value):result[key]=[result[key],value];return result}
async function jsonBody(req){const chunks=[];let size=0;for await(const c of req){size+=c.length;if(size>1000000){const e=new Error('too large');e.statusCode=413;throw e}chunks.push(c)}const raw=Buffer.concat(chunks).toString();return raw?JSON.parse(raw):{}}
function safe(a,b){const x=Buffer.from(String(a||'')),y=Buffer.from(String(b||''));return x.length===y.length&&x.length>0&&crypto.timingSafeEqual(x,y)}
function guard(res,user,s,key,fn){return allowed(user.role,key)?fn():html(res,403,layout(user,s,'Akses ditolak','',messageView('Akses tidak tersedia','Peran akun Anda tidak memiliki izin.')))}
function asset(p,res){const n=path.basename(p);if(!['app.css','integrations.css','growth.css','app.js'].includes(n))return text(res,404,'Not found');res.setHeader('Cache-Control','no-cache, must-revalidate');return text(res,200,fs.readFileSync(path.join(ROOT,'public',n)),n.endsWith('.css')?'text/css; charset=utf-8':'text/javascript; charset=utf-8')}
function serveMedia(pathname,res){const match=pathname.match(/^\/media\/([a-f0-9-]{36}\.(png|jpg|webp))$/);if(!match)return text(res,404,'Not found');const file=path.join(MEDIA_DIR,match[1]);if(!fs.existsSync(file))return text(res,404,'Not found');const types={png:'image/png',jpg:'image/jpeg',webp:'image/webp'},data=fs.readFileSync(file);res.statusCode=200;res.setHeader('Content-Type',types[match[2]]);res.setHeader('Content-Length',data.length);res.setHeader('Cache-Control','public, max-age=31536000, immutable');res.end(data)}
function saveImageData(data){const raw=String(data||''),match=raw.match(/^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/=]+)$/);if(!match)throw new Error('Format gambar harus JPG, PNG, atau WebP.');const bytes=Buffer.from(match[2],'base64');if(!bytes.length||bytes.length>4_000_000)throw new Error('Ukuran gambar maksimal 4 MB.');const valid=match[1]==='png'?bytes.subarray(0,4).toString('hex')==='89504e47':match[1]==='jpeg'?bytes.subarray(0,3).toString('hex')==='ffd8ff':bytes.subarray(0,4).toString()==='RIFF'&&bytes.subarray(8,12).toString()==='WEBP';if(!valid)throw new Error('Isi file gambar tidak valid.');fs.mkdirSync(MEDIA_DIR,{recursive:true});const filename=`${crypto.randomUUID()}.${match[1]==='jpeg'?'jpg':match[1]}`;fs.writeFileSync(path.join(MEDIA_DIR,filename),bytes,{mode:0o644});return filename}
function publicMediaUrl(req,filename){const configured=String(process.env.APP_URL||'').replace(/\/+$/,'');if(configured)return `${configured}/media/${filename}`;const proto=String(req.headers['x-forwarded-proto']||'http').split(',')[0].trim(),host=String(req.headers['x-forwarded-host']||req.headers.host||'localhost').split(',')[0].trim();return `${proto}://${host}/media/${filename}`}
function mediaHref(value){try{const url=new URL(String(value||''));return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return''}}
function values(value){return(Array.isArray(value)?value:[value]).map(x=>String(x||'')).filter(Boolean)}
function wait(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
function headers(res){res.setHeader('Content-Security-Policy',"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; img-src 'self' data: https:; form-action 'self'; frame-ancestors 'none'; base-uri 'self'");res.setHeader('X-Frame-Options','DENY');res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Referrer-Policy','same-origin');res.setHeader('Permissions-Policy','camera=(), microphone=(), geolocation=()');res.setHeader('Cache-Control','no-store')}
function html(res,s,b){return text(res,s,b,'text/html; charset=utf-8')}function json(res,s,b){return text(res,s,JSON.stringify(b),'application/json')}function text(res,s,b,t='text/plain; charset=utf-8'){res.statusCode=s;res.setHeader('Content-Type',t);res.end(b)}function redirect(res,l){res.statusCode=303;res.setHeader('Location',l);res.end()}
function download(res,file,name,type){res.statusCode=200;res.setHeader('Content-Type',type);res.setHeader('Content-Disposition',`attachment; filename="${name}"`);fs.createReadStream(file).pipe(res)}
function csv(res,k){const rows=state[k],keys=[...new Set(rows.flatMap(Object.keys))].filter(x=>x!=='passwordHash'),e=v=>`"${String(v??'').replaceAll('"','""')}"`;res.statusCode=200;res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename="${k}-${today()}.csv"`);res.end('\ufeff'+[keys.map(e).join(','),...rows.map(r=>keys.map(k=>e(r[k])).join(','))].join('\r\n'))}
function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
function cell(k,v){if(['status','role','format'].includes(k))return `<span class="badge">${esc(v||'-')}</span>`;if(k==='active')return v?'Aktif':'Tidak';const x=esc(v??'-');return x.length>100?`${x.slice(0,100)}…`:x}
function wa(p,m){return `https://wa.me/${String(p).replace(/\D/g,'').replace(/^0/,'62')}?text=${encodeURIComponent(m)}`}
function empty(t){return `<div class="empty">${esc(t)}</div>`}function initials(n){return String(n||'SM').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}function today(){return new Date().toISOString().slice(0,10)}function dateShort(v){if(!v)return'-';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',timeZone:'Asia/Jakarta'}).format(d)}function dateTimeShort(v){if(!v)return'-';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(d)}function pct(v){return `${Math.round(v*100)}%`}function formatBytes(v){const n=Number(v)||0;if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`}
